import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import RevenueForecastDashboard from './RevenueForecastDashboard';
import UploadPage from './UploadPage';
import BaselineDetailsPage from './BaselineDetailsPage';
import BfdDetailsPage from './BfdDetailsPage';
import MostLikelyDetailsPage from './MostLikelyDetailsPage';
import UpsideDetailsPage from './UpsideDetailsPage';

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<RevenueForecastDashboard />} />
        <Route path="/upload" element={<UploadPage />} />
        <Route path="/baseline-details" element={<BaselineDetailsPage />} />
        <Route path="/bfd-details" element={<BfdDetailsPage />} />
        <Route path="/mostlikely-details" element={<MostLikelyDetailsPage />} />
        <Route path="/upside-details" element={<UpsideDetailsPage />} />
      </Routes>
    </Router>
  );
}

export default App;
